import {populationCohorts,INITIAL_CENSUS_SHARES,CENSUS_AGES} from './demographics.js?v=courtyard-apartments-1';
// Original age participation calibration, normalized to the former 50% starting baseline.
const PARTICIPATION=[0,.35,.78,.8,.8,.65,.2,.04],NORMALIZER=.5/INITIAL_CENSUS_SHARES.reduce((sum,w,i)=>sum+w*PARTICIPATION[i],0);
const healthFactor=c=>(.5+(Math.max(45,Math.min(90,c.civic.lifeExpectancy))-59)*.004)/.5;
function ageRows(c,population,health=true){const factor=health?healthFactor(c):1;return populationCohorts(c,population).map((people,i)=>{const rate=Math.min(1,PARTICIPATION[i]*NORMALIZER*factor);return{age:CENSUS_AGES[i],people,rate,workers:people*rate};});}
export function workforceShare(c,population=c.stats.population||0){if(!population)return 0;return Math.round(ageRows(c,population).reduce((s,r)=>s+r.workers,0)/population*1e12)/1e12;}
export function workforceOutlook(c){const population=c.stats.population||0,share=workforceShare(c),baseline=ageRows(c,population,false).reduce((s,r)=>s+r.workers,0);return{share,lifeExpectancy:c.civic.lifeExpectancy,baseline,workers:population*share,healthDifference:population*share-baseline,ageDifference:baseline-population*.5,rows:ageRows(c,population)};}
export function workforceAgeTable(c){const w=workforceOutlook(c),fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:1});return `<h3>Workforce by age</h3><div class="table-scroll"><table><thead><tr><th>Age</th><th>Participation</th><th>Potential workers</th></tr></thead><tbody>${w.rows.map(r=>`<tr><td>${r.age}</td><td>${fmt(r.rate*100)}%</td><td>${fmt(r.workers)}</td></tr>`).join('')}</tbody></table></div><p>Children under 15 do not work. Adult and older-age participation differs, so an aging city changes the labor supply. Health adjusts participation within these bands. At baseline health, this age mix supplies ${fmt(Math.abs(w.ageDifference))} ${w.ageDifference>=0?'more':'fewer'} workers than the starting age mix at the same population. Rates are reconstruction estimates; potential workers still need reachable jobs. Age groups are distributed uniformly across occupied homes.</p>`;}
